package com.yeyamo_mobile.api.partner_service.interfaces.rest;
import java.util.*;import org.slf4j.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.partner_service.application.PartnerException;import jakarta.servlet.http.HttpServletRequest;
@RestControllerAdvice public class GlobalExceptionHandler{private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class);@ExceptionHandler(PartnerException.class)ResponseEntity<ErrorResponse>business(PartnerException e,HttpServletRequest r){return ResponseEntity.status(e.getStatus()).body(ErrorResponse.of(e.getCode(),e.getMessage(),List.of(),r.getHeader("X-Correlation-ID")));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ErrorResponse>validation(MethodArgumentNotValidException e,HttpServletRequest r){var d=e.getBindingResult().getFieldErrors().stream().map(x->new ErrorResponse.FieldError(x.getField(),x.getDefaultMessage())).toList();return ResponseEntity.badRequest().body(ErrorResponse.of("VALIDATION_ERROR","Données invalides",d,r.getHeader("X-Correlation-ID")));}@ExceptionHandler(Exception.class)ResponseEntity<ErrorResponse>unexpected(Exception e,HttpServletRequest r){log.error("Unexpected partner-service error",e);return ResponseEntity.status(500).body(ErrorResponse.of("INTERNAL_ERROR","Une erreur interne est survenue",List.of(),r.getHeader("X-Correlation-ID")));}}
